#[allow(dead_code)]
mod common;
#[allow(unused_imports)]
use common::{distinct, equal, ordered};
use std::ops::{Add, Neg, Sub};
use timetuck::SimpleScore;

#[test]
fn parse_score() {
    assert_eq!(
        "-147".parse::<SimpleScore>().unwrap(),
        SimpleScore::new(-147)
    );
    assert_eq!(
        "*".parse::<SimpleScore>().unwrap(),
        SimpleScore::new(i64::MIN)
    );
    assert_eq!(
        "-1structural/-147".parse::<SimpleScore>().unwrap(),
        SimpleScore::new(-147).with_structural(-1)
    );
}

#[test]
fn feasible() {
    assert!(!(SimpleScore::new(0).with_structural(-1)).is_feasible());
    assert!((SimpleScore::new(0)).is_feasible());
    assert!((SimpleScore::new(-5)).is_feasible());
}

#[test]
fn to_short_string() {
    assert_eq!(SimpleScore::new(0).to_short_string(), "0");
    assert_eq!(SimpleScore::new(-147).to_short_string(), "-147");
    assert_eq!(
        SimpleScore::new(-147).with_structural(-1).to_short_string(),
        "-1structural/-147"
    );
}

#[test]
fn test_to_string() {
    assert_eq!((SimpleScore::new(0)).to_string(), "0");
    assert_eq!((SimpleScore::new(-147)).to_string(), "-147");
    assert_eq!(
        (SimpleScore::new(-147).with_structural(-1)).to_string(),
        "-1structural/-147"
    );
}

#[test]
fn parse_score_illegal_argument() {
    assert!("-147hard/-258soft".parse::<SimpleScore>().is_err());
    assert!("-1structural/-147hard".parse::<SimpleScore>().is_err());
}

#[test]
fn add() {
    assert_eq!(
        SimpleScore::new(20).add(SimpleScore::new(-1)),
        SimpleScore::new(19)
    );
}

#[test]
fn subtract() {
    assert_eq!(
        SimpleScore::new(20).sub(SimpleScore::new(-1)),
        SimpleScore::new(21)
    );
}

#[test]
fn multiply() {
    assert_eq!(SimpleScore::new(5).multiply(1.2), SimpleScore::new(6));
    assert_eq!(SimpleScore::new(1).multiply(1.2), SimpleScore::new(1));
    assert_eq!(SimpleScore::new(4).multiply(1.2), SimpleScore::new(4));
}

#[test]
fn divide() {
    assert_eq!(SimpleScore::new(25).divide(5.0), SimpleScore::new(5));
    assert_eq!(SimpleScore::new(21).divide(5.0), SimpleScore::new(4));
    assert_eq!(SimpleScore::new(24).divide(5.0), SimpleScore::new(4));
}

#[test]
fn power() {
    assert_eq!(SimpleScore::new(5).power(2.0), SimpleScore::new(25));
    assert_eq!(SimpleScore::new(25).power(0.5), SimpleScore::new(5));
}

#[test]
fn negate() {
    assert_eq!(SimpleScore::new(5).neg(), SimpleScore::new(-5));
    assert_eq!(SimpleScore::new(-5).neg(), SimpleScore::new(5));
}

#[test]
fn abs() {
    assert_eq!(SimpleScore::new(5).abs(), SimpleScore::new(5));
    assert_eq!(SimpleScore::new(-5).abs(), SimpleScore::new(5));
}

#[test]
fn zero() {
    assert_eq!(SimpleScore::ZERO, SimpleScore::new(0));
    assert!(SimpleScore::ZERO.is_zero());
    assert!(!SimpleScore::new(1).is_zero());
}

#[test]
fn equals_and_hash_code() {
    equal(&[SimpleScore::new(-10), SimpleScore::new(-10)]);
    equal(&[
        SimpleScore::new(-10).with_structural(-1),
        SimpleScore::new(-10).with_structural(-1),
    ]);
    distinct(&[
        SimpleScore::new(-10),
        SimpleScore::new(-30),
        SimpleScore::new(-10).with_structural(-1),
    ]);
}

#[test]
fn compare_to() {
    ordered(&[
        SimpleScore::new((i32::MIN as i64) - 4000).with_structural(-1),
        SimpleScore::new((i32::MIN as i64) - 4000),
        SimpleScore::new(-300),
        SimpleScore::new(-20),
        SimpleScore::new(-1),
        SimpleScore::new(0),
        SimpleScore::new(1),
        SimpleScore::new((i32::MAX as i64) + 4000),
    ]);
}
